import { z } from 'zod'; // npm install zod

// ── 1. Input validation with Zod schema ───────────────────────
const CreateUserSchema = z.object({
  email:    z.string().email().max(255).toLowerCase().trim(),
  name:     z.string().min(1).max(100).regex(/^[\w\s'-]+$/, 'Invalid name characters'),
  age:      z.number().int().min(13).max(120),
  role:     z.enum(['viewer', 'editor', 'admin']).default('viewer'), // Allow-list of valid values
  website:  z.string().url().optional(),
});

function validateCreateUser(rawInput) {
  const result = CreateUserSchema.safeParse(rawInput);
  if (!result.success) {
    // Return structured validation errors, never expose internal details
    return { ok: false, errors: result.error.flatten().fieldErrors };
  }
  return { ok: true, data: result.data };
}

console.log(validateCreateUser({ email: ' ALICE@EXAMPLE.COM ', name: 'Alice', age: 25, role: 'admin' }));
// => { ok: true, data: { email: 'alice@example.com', name: 'Alice', age: 25, role: 'admin' } }

console.log(validateCreateUser({ email: 'not-an-email', age: 'old' }));
// => { ok: false, errors: { email: ['Invalid email'], age: [...], name: [...] } }

// ── 2. Secrets management — read from environment only ────────
function loadConfig() {
  const required = ['DATABASE_URL', 'JWT_SECRET', 'REDIS_URL'];
  const missing = required.filter(k => !process.env[k]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
  return {
    db:  process.env.DATABASE_URL,      // Never hardcoded
    jwt: process.env.JWT_SECRET,         // Rotatable without code change
    redis: process.env.REDIS_URL,
    // In production: fetched from AWS Secrets Manager / HashiCorp Vault at startup
  };
}

