// ── 5. Defense in depth: rate limiting + input validation + auth
function createRateLimiter(windowMs, maxRequests) {
  const counts = new Map();
  return (req, res, next) => {
    const key = req.ip;
    const now = Date.now();
    const entry = counts.get(key) || { count: 0, resetAt: now + windowMs };
    if (now > entry.resetAt) { entry.count = 0; entry.resetAt = now + windowMs; }
    entry.count++;
    counts.set(key, entry);
    if (entry.count > maxRequests) {
      return res.status(429).json({ error: 'Too many requests' });
    }
    next();
  };
}
// Apply: app.use('/login', createRateLimiter(15 * 60 * 1000, 10)); // 10 attempts per 15 min

// ── Secrets management tiers ──────────────────────────────────
//
// Tier │ Storage                     │ Access Pattern              │ Use for
// ─────┼─────────────────────────────┼─────────────────────────────┼──────────────────
// 1    │ Hardcoded in source code    │ Anyone with repo access      │ NEVER
// 2    │ .env file (not in .gitignore)│ Anyone with file access     │ NEVER in production
// 3    │ .env file (gitignored)      │ Local dev only              │ Local dev only
// 4    │ CI/CD secrets (GitHub/GitLab)│ CI runners only             │ Build & deploy secrets
// 5    │ Cloud secrets manager       │ IAM-controlled, audited     │ Production secrets
// 6    │ HSM / dedicated vault       │ Hardware-enforced, rotation  │ PKI keys, payment

// ── .gitignore essentials to prevent accidental commits ───────
const GITIGNORE_PATTERNS = [
  '.env',
  '.env.*',
  '*.pem',
  '*.key',
  '*.p12',
  '*.pfx',
  'secrets.json',
  'credentials.json',
  'service-account*.json', // GCP service accounts
  '**/*.env',
];

// ── Security headers every HTTP response should include ────────
const SECURITY_HEADERS = {
  'Strict-Transport-Security':  'max-age=63072000; includeSubDomains',  // HSTS
  'X-Content-Type-Options':     'nosniff',            // Prevent MIME sniffing
  'X-Frame-Options':            'DENY',               // Prevent clickjacking
  'Referrer-Policy':            'strict-origin-when-cross-origin',
  'Permissions-Policy':         'geolocation=(), microphone=(), camera=()', // Restrict browser APIs
  'Content-Security-Policy':    "default-src 'self'; script-src 'self'",
};

